// Type: Funder.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub enum Funder {
    Task(Task),
    Pool(Pool),
    Recurring(Recurring),
    Period(Period),
}

// Record: Funder.
impl Record for Funder {
    type Limits = Limits;
    const TAIL: Path = paths::FUNDER_TAG;

    fn encoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 159)?.encoded)
    }

    fn decoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 159)?.decoded)
    }

    fn write(&self, limits: &Limits, out: &mut skein_lib::Writer) -> Result<(), Problem> {
        match self {
            Self::Task(value) => { field::put(out, &[0], paths::FUNDER_TAG)?; value.write(limits, out) },
            Self::Pool(value) => { field::put(out, &[1], paths::FUNDER_TAG)?; value.write(limits, out) },
            Self::Recurring(value) => { field::put(out, &[2], paths::FUNDER_TAG)?; value.write(limits, out) },
            Self::Period(value) => { field::put(out, &[3], paths::FUNDER_TAG)?; value.write(limits, out) },
        }
    }

    fn read(limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        let tag = reader.u8().ok_or(Problem { path: paths::FUNDER_TAG, reason: skein_codec::Reason::Short })?;
        match tag {
            0 => Ok(Self::Task(Task::read(limits, reader)?)),
            1 => Ok(Self::Pool(Pool::read(limits, reader)?)),
            2 => Ok(Self::Recurring(Recurring::read(limits, reader)?)),
            3 => Ok(Self::Period(Period::read(limits, reader)?)),
            4..=u8::MAX => Err(Problem { path: paths::FUNDER_TAG, reason: skein_codec::Reason::Tag }),
        }
    }
}

