pub enum TaskResult {
    Approved(Approved),
    Report(ReportResult),
    Verdict(VerdictResult),
    Change(ChangeResult),
    Failure(FailureResult),
    NoChange(ReportResult),
    Job(JobResult),
}

// Record: TaskResult.
impl Record for TaskResult {
    type Limits = Limits;
    const TAIL: Path = paths::TASK_RESULT_TAG;

    fn encoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 267)?.encoded)
    }

    fn decoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 267)?.decoded)
    }

    fn write(&self, limits: &Limits, out: &mut skein_lib::Writer) -> Result<(), Problem> {
        match self {
            Self::Approved(value) => { field::put(out, &[0], paths::TASK_RESULT_TAG)?; value.write(limits, out) },
            Self::Report(value) => { field::put(out, &[1], paths::TASK_RESULT_TAG)?; value.write(limits, out) },
            Self::Verdict(value) => { field::put(out, &[2], paths::TASK_RESULT_TAG)?; value.write(limits, out) },
            Self::Change(value) => { field::put(out, &[3], paths::TASK_RESULT_TAG)?; value.write(limits, out) },
            Self::Failure(value) => { field::put(out, &[4], paths::TASK_RESULT_TAG)?; value.write(limits, out) },
            Self::NoChange(value) => { field::put(out, &[5], paths::TASK_RESULT_TAG)?; value.write(limits, out) },
            Self::Job(value) => { field::put(out, &[6], paths::TASK_RESULT_TAG)?; value.write(limits, out) },
        }
    }

    fn read(limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        let tag = reader.u8().ok_or(Problem { path: paths::TASK_RESULT_TAG, reason: skein_codec::Reason::Short })?;
        match tag {
            0 => Ok(Self::Approved(Approved::read(limits, reader)?)),
            1 => Ok(Self::Report(ReportResult::read(limits, reader)?)),
            2 => Ok(Self::Verdict(VerdictResult::read(limits, reader)?)),
            3 => Ok(Self::Change(ChangeResult::read(limits, reader)?)),
            4 => Ok(Self::Failure(FailureResult::read(limits, reader)?)),
            5 => Ok(Self::NoChange(ReportResult::read(limits, reader)?)),
            6 => Ok(Self::Job(JobResult::read(limits, reader)?)),
            7..=u8::MAX => Err(Problem { path: paths::TASK_RESULT_TAG, reason: skein_codec::Reason::Tag }),
        }
    }
}

