// Type: SettingsOutcome.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub enum SettingsOutcome {
    Accepted(SettingsAcceptedRevision),
    Rejected,
    Stale(SettingsStaleRevision),
}

// Record: SettingsOutcome.
impl Record for SettingsOutcome {
    type Limits = Limits;
    const TAIL: Path = paths::SETTINGS_OUTCOME_TAG;

    fn encoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 529)?.encoded)
    }

    fn decoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 529)?.decoded)
    }

    fn write(&self, limits: &Limits, out: &mut skein_lib::Writer) -> Result<(), Problem> {
        match self {
            Self::Accepted(value) => { field::put(out, &[0], paths::SETTINGS_OUTCOME_TAG)?; value.write(limits, out) },
            Self::Rejected => field::put(out, &[1], paths::SETTINGS_OUTCOME_TAG),
            Self::Stale(value) => { field::put(out, &[2], paths::SETTINGS_OUTCOME_TAG)?; value.write(limits, out) },
        }
    }

    fn read(limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        let tag = reader.u8().ok_or(Problem { path: paths::SETTINGS_OUTCOME_TAG, reason: skein_codec::Reason::Short })?;
        match tag {
            0 => Ok(Self::Accepted(SettingsAcceptedRevision::read(limits, reader)?)),
            1 => Ok(Self::Rejected),
            2 => Ok(Self::Stale(SettingsStaleRevision::read(limits, reader)?)),
            3..=u8::MAX => Err(Problem { path: paths::SETTINGS_OUTCOME_TAG, reason: skein_codec::Reason::Tag }),
        }
    }
}

