// Type: LiveRoom.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub enum LiveRoom {
    Deployment,
    Project(RoomProject),
}

// Record: LiveRoom.
impl Record for LiveRoom {
    type Limits = Limits;
    const TAIL: Path = paths::LIVE_ROOM_TAG;

    fn encoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 835)?.encoded)
    }

    fn decoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 835)?.decoded)
    }

    fn write(&self, limits: &Limits, out: &mut skein_lib::Writer) -> Result<(), Problem> {
        match self {
            Self::Deployment => field::put(out, &[0], paths::LIVE_ROOM_TAG),
            Self::Project(value) => { field::put(out, &[1], paths::LIVE_ROOM_TAG)?; value.write(limits, out) },
        }
    }

    fn read(limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        let tag = reader.u8().ok_or(Problem { path: paths::LIVE_ROOM_TAG, reason: skein_codec::Reason::Short })?;
        match tag {
            0 => Ok(Self::Deployment),
            1 => Ok(Self::Project(RoomProject::read(limits, reader)?)),
            2..=u8::MAX => Err(Problem { path: paths::LIVE_ROOM_TAG, reason: skein_codec::Reason::Tag }),
        }
    }
}

