// Type: Value.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub enum Value {
    Ledger(FundingRecord),
    ClosedLedger(FundingRecord),
    Writer(WriterSlot),
    Pool(PoolSlots),
    History(Box<History>),
    PersonProposal(PersonProposal),
    DecidedProposal(PersonProposal),
    Activity(ActivityLine),
    Ended(BeforeTalk),
    Stub(Stub),
    Update(Update),
    Result(ResultRow),
    EndedDelegate(Edge),
    Delegate(Edge),
    EndedByParty(EndedByParty),
    EndedByProject(EndedByProject),
    PlacedHold(PlacedHold),
    EndedTalk(TaskRecord),
    Attempt(AttemptRow),
    Hold(HoldRow),
    LiveHot(LiveHot),
    LiveCold(LiveCold),
    Summary(Box<TaskSummary>),
    Retention(RetentionRow),
}

// Record: Value.
impl Record for Value {
    type Limits = Limits;
    const TAIL: Path = paths::VALUE_TAG;

    fn encoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 999)?.encoded)
    }

    fn decoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 999)?.decoded)
    }

    fn write(&self, limits: &Limits, out: &mut skein_lib::Writer) -> Result<(), Problem> {
        match self {
            Self::Ledger(value) => { field::put(out, &[0], paths::VALUE_TAG)?; value.write(limits, out) },
            Self::ClosedLedger(value) => { field::put(out, &[1], paths::VALUE_TAG)?; value.write(limits, out) },
            Self::Writer(value) => { field::put(out, &[2], paths::VALUE_TAG)?; value.write(limits, out) },
            Self::Pool(value) => { field::put(out, &[3], paths::VALUE_TAG)?; value.write(limits, out) },
            Self::History(value) => { field::put(out, &[4], paths::VALUE_TAG)?; value.write(limits, out) },
            Self::PersonProposal(value) => { field::put(out, &[5], paths::VALUE_TAG)?; value.write(limits, out) },
            Self::DecidedProposal(value) => { field::put(out, &[6], paths::VALUE_TAG)?; value.write(limits, out) },
            Self::Activity(value) => { field::put(out, &[7], paths::VALUE_TAG)?; value.write(limits, out) },
            Self::Ended(value) => { field::put(out, &[8], paths::VALUE_TAG)?; value.write(limits, out) },
            Self::Stub(value) => { field::put(out, &[9], paths::VALUE_TAG)?; value.write(limits, out) },
            Self::Update(value) => { field::put(out, &[10], paths::VALUE_TAG)?; value.write(limits, out) },
            Self::Result(value) => { field::put(out, &[11], paths::VALUE_TAG)?; value.write(limits, out) },
            Self::EndedDelegate(value) => { field::put(out, &[12], paths::VALUE_TAG)?; value.write(limits, out) },
            Self::Delegate(value) => { field::put(out, &[13], paths::VALUE_TAG)?; value.write(limits, out) },
            Self::EndedByParty(value) => { field::put(out, &[14], paths::VALUE_TAG)?; value.write(limits, out) },
            Self::EndedByProject(value) => { field::put(out, &[15], paths::VALUE_TAG)?; value.write(limits, out) },
            Self::PlacedHold(value) => { field::put(out, &[16], paths::VALUE_TAG)?; value.write(limits, out) },
            Self::EndedTalk(value) => { field::put(out, &[17], paths::VALUE_TAG)?; value.write(limits, out) },
            Self::Attempt(value) => { field::put(out, &[18], paths::VALUE_TAG)?; value.write(limits, out) },
            Self::Hold(value) => { field::put(out, &[19], paths::VALUE_TAG)?; value.write(limits, out) },
            Self::LiveHot(value) => { field::put(out, &[20], paths::VALUE_TAG)?; value.write(limits, out) },
            Self::LiveCold(value) => { field::put(out, &[21], paths::VALUE_TAG)?; value.write(limits, out) },
            Self::Summary(value) => { field::put(out, &[22], paths::VALUE_TAG)?; value.write(limits, out) },
            Self::Retention(value) => { field::put(out, &[23], paths::VALUE_TAG)?; value.write(limits, out) },
        }
    }

    fn read(limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        let tag = reader.u8().ok_or(Problem { path: paths::VALUE_TAG, reason: skein_codec::Reason::Short })?;
        match tag {
            0 => Ok(Self::Ledger(FundingRecord::read(limits, reader)?)),
            1 => Ok(Self::ClosedLedger(FundingRecord::read(limits, reader)?)),
            2 => Ok(Self::Writer(WriterSlot::read(limits, reader)?)),
            3 => Ok(Self::Pool(PoolSlots::read(limits, reader)?)),
            4 => Ok(Self::History(Box::new(History::read(limits, reader)?))),
            5 => Ok(Self::PersonProposal(PersonProposal::read(limits, reader)?)),
            6 => Ok(Self::DecidedProposal(PersonProposal::read(limits, reader)?)),
            7 => Ok(Self::Activity(ActivityLine::read(limits, reader)?)),
            8 => Ok(Self::Ended(BeforeTalk::read(limits, reader)?)),
            9 => Ok(Self::Stub(Stub::read(limits, reader)?)),
            10 => Ok(Self::Update(Update::read(limits, reader)?)),
            11 => Ok(Self::Result(ResultRow::read(limits, reader)?)),
            12 => Ok(Self::EndedDelegate(Edge::read(limits, reader)?)),
            13 => Ok(Self::Delegate(Edge::read(limits, reader)?)),
            14 => Ok(Self::EndedByParty(EndedByParty::read(limits, reader)?)),
            15 => Ok(Self::EndedByProject(EndedByProject::read(limits, reader)?)),
            16 => Ok(Self::PlacedHold(PlacedHold::read(limits, reader)?)),
            17 => Ok(Self::EndedTalk(TaskRecord::read(limits, reader)?)),
            18 => Ok(Self::Attempt(AttemptRow::read(limits, reader)?)),
            19 => Ok(Self::Hold(HoldRow::read(limits, reader)?)),
            20 => Ok(Self::LiveHot(LiveHot::read(limits, reader)?)),
            21 => Ok(Self::LiveCold(LiveCold::read(limits, reader)?)),
            22 => Ok(Self::Summary(Box::new(TaskSummary::read(limits, reader)?))),
            23 => Ok(Self::Retention(RetentionRow::read(limits, reader)?)),
            24..=u8::MAX => Err(Problem { path: paths::VALUE_TAG, reason: skein_codec::Reason::Tag }),
        }
    }
}

